def strategy(hist, state, pos, ind) -> dict:
    close = hist.close[-1]
    sma200 = ind.sma(hist.close, 200)[-1]
    sma5 = ind.sma(hist.close, 5)[-1]
    rsi2 = ind.rsi(hist.close, 2)[-1]

    # Check exit conditions first
    if pos > 0:
        # Long: exit if close above 5-bar SMA
        if close > sma5:
            state['in_trade'] = False
            pos = 0.0
    elif pos < 0:
        # Short: exit if close below 5-bar SMA
        if close < sma5:
            state['in_trade'] = False
            pos = 0.0

    # Check entry conditions (only if flat)
    if pos == 0.0:
        # Long entry: close above 200 SMA and RSI(2) <= 10
        if close > sma200 and rsi2 <= 10:
            return {"target": 1.0, "stop": None, "take": None}
        # Short entry: close below 200 SMA and RSI(2) >= 90
        elif close < sma200 and rsi2 >= 90:
            return {"target": -1.0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    current_close = hist.close[-1]
    current_time = hist.time[-1]

    # Initialize on first bar
    if len(hist) == 1:
        state['entry_time'] = current_time
        state['entry_price'] = current_close
        state['highest_close'] = current_close
        state['period_start_time'] = current_time
        return {"target": 1.0, "stop": None, "take": None}

    # Check if we need to start a new period (31 days = 31 * 24 * 60 * 60 * 1000 ms)
    period_duration_ms = 31 * 24 * 60 * 60 * 1000
    time_since_period_start = current_time - state['period_start_time']

    # If a new period has started and we're flat, buy
    if pos == 0.0 and time_since_period_start >= period_duration_ms:
        state['entry_time'] = current_time
        state['entry_price'] = current_close
        state['highest_close'] = current_close
        state['period_start_time'] = current_time
        return {"target": 1.0, "stop": None, "take": None}

    # If we're long, track the highest close and check for 1% trailing exit
    if pos > 0.0:
        # Update highest close if current close is higher
        if current_close > state['highest_close']:
            state['highest_close'] = current_close

        # Check if close is more than 1% below the highest close
        threshold = state['highest_close'] * 0.99
        if current_close < threshold:
            # Sell everything
            return {"target": 0.0, "stop": None, "take": None}

        # Stay long
        return {"target": pos, "stop": None, "take": None}

    # If we're flat and not yet in a new period, stay flat
    return {"target": 0.0, "stop": None, "take": None}
